 design={'version':'STRUCTURAL_EVIDENCE_CONTRACT_V1_1_DESIGN','status':'DESIGN_ONLY_BOUNDED_REVISION','verified_inputs':{n:h(n) for n in ['ETHOS_STRUCTURAL_EVIDENCE_CONTRACT_V1_DESIGN.md','ethos_structural_evidence_contract_v1_design.json','ethos_task12v_structural_contract_adversarial_review.json','ethos_task12v_attack_matrix.json','sloth_contextual_measurement_v21_research.py']},
 'preserved_v1':['immutable assertion envelopes','assertor/actor/observer/verifier separation','many-to-many actors and targets','scoped identities','task/event/provenance/verification/lineage/conflict/UNKNOWN','fact-specific authority outside shared truth','temporal availability','N=1/N>1 common model','regulator neutrality'],
 'data_partitions':{'STRUCTURAL':'Only contract-versioned, vocabulary-recognized, conformance-valid records. Eligible only after external authority and temporal-consumption policy.','OPAQUE':'Retained/loggable producer data and unknown extensions; cannot establish relation/state/outcome/authority/verification/identity/phase or become regulator-consumable structural evidence.','QUARANTINED':'Recognizable input failing structural conformance or unsupported vocabulary; retained with reason, non-consumable.','REJECTED':'Invalid identity/integrity/cycle/conflicting-ID input; not structural and no silent placeholder created.'},
 'vocabulary_boundary':{'relation_state_outcome_context':'Each uses a contract/version-owned finite neutral vocabulary with endpoint/type constraints. Unknown type or unsupported version is QUARANTINED (or REJECTED for integrity-malformed records), never guessed/mapped/consumed.','domain_extensions':'Opaque by default. A future structural extension requires separately registered neutral vocabulary/version and conformance review; producer-defined names never become structural.','prohibited_examples':['slothful','abandoning','greedy','unethical','unethical_success','responsibility_displacement','RAF/TCF contribution or score']},
 'authority_boundary':{'producer_may_supply':['claimed identity','source class','assertion content','evidence references'],'producer_may_not_supply_effectively':['authority','trust','priority','precedence','verification strength','independence'],'rule':'Payload fields bearing those names are OPAQUE and have no authority effect. External fact-specific authority evaluation is a separate policy/admission output; if referenced, authority_decision_ref must identify an externally produced decision and is not producer-controlled. Verification record remains distinct from authority decision.'},
 'conformance':{'ACCEPT':'Well-formed recognized structural record; not automatically authoritative or consumable.','ACCEPT_OPAQUE':'Valid envelope carrying opaque payload only; payload is non-structural.','QUARANTINE':'Unsupported vocabulary/version, unresolved reference, invalid/unknown phase, incomplete derivation/verification; retained with reason and non-consumable.','REJECT':'Integrity-invalid records: conflicting duplicate ID, endpoint type mismatch, impossible reference form, derivation cycle, required identity absent.','UNKNOWN':'Representable factual unknown; not a malformed-record fallback and not structural permission.'},
 'deterministic_rules':{'endpoint_types':'Every relation vocabulary entry declares permitted endpoint entity categories/role cardinality. Mismatch is REJECT; a target type may not be consumer-selected.','references':'Missing entity/event/task/assertion/evidence references are QUARANTINED pending authoritative resolution; no fabricated placeholder.','duplicates':'Exact same-ID/same-canonical-content replay is idempotent; same ID/different content is REJECT with conflict/integrity record; never overwrite.','phase':'Malformed/unknown/unsupported phase is QUARANTINED; no default PRE_ACTION. Impossible transition is REJECT.','verification':'A claimed VERIFIED status without valid verifier identity and evidence/method reference is QUARANTINED and cannot retain VERIFIED structural status.','derivation':'Derived facts require parent IDs, supported parent versions, derivation rule/version, derivation time, and acyclic lineage. Missing/invalid parents quarantine; cycle rejects; derivation never increases authority.','versions':'Unsupported relation/state/outcome/authorization/assignment/context vocabulary version or unknown type quarantines at record granularity.'},
 'target_temporal':{'target_typing':'Target relation requires referenced entity category from controlled neutral set (e.g., TASK, OBJECT, PARTICIPANT, RESOURCE, SERVICE, ENVIRONMENT, UNKNOWN). Claimed type inconsistent with registered entity is REJECT. UNKNOWN target is legal but consumers requiring target identity must not substitute a default. Many targets remain relation records; no primary inferred.','temporal_consumption':'A consumer declares evaluation timestamp, availability phase/boundary, and scope. It may consume only structurally accepted/admitted evidence whose availability is valid at that boundary. Event time never substitutes for availability time. Missing availability quarantines.','replay':'Historical replay selects evidence by original evaluation boundary; later evidence may be shown separately but cannot contaminate reconstruction.'},
 'traceability':{'b-036':'CLOSED: typed targets represent stop(E,timer) distinctly from task T; no target-to-task inference. This requires authoritative supply, not prose parsing.','tcf-11/tcf-13/tcf-14/both-07':'PARTIALLY_REPRESENTABLE: event/task/target/order/completion/availability prerequisites are neutral and representable if supplied; V1.1 adds no TCF conclusion or extraction.','neg-03':'CLOSED structurally: actor/event/task/role/target may be separate typed facts; no responsibility-displacement predicate is allowed.'},
 'invariants':['opaque metadata cannot create structural truth','unsupported vocabulary cannot create structural truth','producers cannot self-grant authority','malformed relations cannot become consumable','derived facts require valid acyclic lineage','target type cannot be guessed','availability cannot default permissively','future evidence cannot affect past decision','consumer boundary constrains selection','verification does not create authority','unknown is not a malformed-record fallback'],
 'readiness':'V1.1 READY FOR ADVERSARIAL DELTA REVIEW'}
 delta={'version':'TASK12W_V1_TO_V1_1_DELTA_V1','changes':[{'area':'state/outcome/extensions/metadata','defect':'semantic escape channels','change':'four data partitions; finite versioned vocabulary; unknown extensions opaque; opaque non-consumable','preserved':'V1 neutral data and lineage retained'},{'area':'authority','defect':'producer self-granted authority','change':'payload authority/trust/priority has no effect; external authority-decision boundary/reference only','preserved':'fact-specific policy stays outside structural truth'},{'area':'conformance','defect':'malformed relation','change':'normative ACCEPT/OPAQUE/QUARANTINE/REJECT/UNKNOWN dispositions plus endpoint/reference/duplicate/phase/verifier/derivation rules','preserved':'immutable assertions/conflict retention'},{'area':'vocabulary','defect':'unsupported vocabulary','change':'unsupported type/version quarantined record-granularly and non-consumable','preserved':'bounded relation architecture'},{'area':'targets/temporal consumption','defect':'target typing and post-action leakage','change':'controlled target categories/type consistency plus consumer-declared evaluation boundary/replay rule','preserved':'many-to-many targets and temporal provenance'}]}
 closure={'version':'TASK12W_DEFECT_CLOSURE_V1','defects':{x:'CLOSED' for x in ['SEMANTIC_ESCAPE_CHANNELS','PRODUCER_SELF_GRANTED_AUTHORITY','MALFORMED_RELATION_CONFORMANCE','UNSUPPORTED_VOCABULARY','TARGET_TYPING_AND_TEMPORAL_CONSUMPTION']},'evidence':['data_partitions + vocabulary_boundary','authority_boundary','conformance + deterministic_rules','vocabulary_boundary + versions','target_temporal + traceability']}
 clar={f'A{n:02d}':('IMPLICATED_BY_REQUIRED_DEFECT_FIX' if n in [1,4,8,9,11,12,15,17,19,22,24,28,30,32,36,37,38] else 'CLARIFICATION_ALREADY_SUFFICIENT') for n in [1,4,8,9,11,12,15,17,19,22,24,28,30,32,36,37,38]};clar['version']='TASK12W_CLARIFICATION_REVIEW_V1';clar['summary']='All 17 Task12V PASS_WITH_CLARIFICATION items are either implicated by a required defect fix or remain sufficient; no feature-creep revision added.'
 design['semantic_fingerprint']=hashlib.sha256(json.dumps(design,sort_keys=True,separators=(',',':')).encode()).hexdigest()
